(6410397, 950631, 12611, '<td valign="top">beautiful tex- mex feel here. Love the subtle green and purple interplay at the bottom.</td>', 'beautiful tex- mex feel here. Love the subtle green and purple interplay at the bottom.', '2011-05-11 08:25:23.000000', NULL, 1),
(6410398, 950546, 12611, '<td valign="top">For some reason, this shot really works; it has a nice artsy- phorjournalistic feel of a seventies or eighties magazine; I think the elements that make the shot are the fence placement; the plant in the foreground, the dog and the striped dress.</td>', 'For some reason, this shot really works; it has a nice artsy- phorjournalistic feel of a seventies or eighties magazine; I think the elements that make the shot are the fence placement; the plant in the foreground, the dog and the striped dress.', '2011-05-11 08:27:13.000000', NULL, 1),
(6410399, 950117, 12611, '<td valign="top">Such marvelous detail.</td>', 'Such marvelous detail.', '2011-05-11 08:27:42.000000', NULL, 1),
