(6410401, 950305, 12611, '<td valign="top">vibrant and alive- yet peaceful; warm sand fenced in by cool water and cool trees. Very nice.</td>', 'vibrant and alive- yet peaceful; warm sand fenced in by cool water and cool trees. Very nice.', '2011-05-11 08:30:16.000000', NULL, 1),
(6410402, 950204, 12611, '<td valign="top">A bit washed out-  but I get the feel of a very humid, palpably wet morning. not rainy, but when you come back home form the walk on the beach you realize that you are soaking wet under the rain slicker you didn''t need to wear. thats the feel I get- and I love the subtlety of the fence.</td>', 'A bit washed out-  but I get the feel of a very humid, palpably wet morning. not rainy, but when you come back home form the walk on the beach you realize that you are soaking wet under the rain slicker you didn''t need to wear. thats the feel I get- and I love the subtlety of the fence.', '2011-05-11 08:31:54.000000', NULL, 1),
(6410403, 950308, 12611, '<td valign="top">dizzying madness; nice work</td>', 'dizzying madness; nice work', '2011-05-11 08:32:22.000000', NULL, 1),
(6410404, 950471, 12611, '<td valign="top">this shot is not easy; you did it well; great placement of the grass.</td>', 'this shot is not easy; you did it well; great placement of the grass.', '2011-05-11 08:32:51.000000', NULL, 1),
(6410406, 950134, 12611, '<td valign="top">alternately titled- "Daddy didn''t hurt that man, and he loves you and will be home soon." but seriously- great shot- nice "find" as we say, and great use of soft dreamy edges.</td>', 'alternately titled- "Daddy didn''t hurt that man, and he loves you and will be home soon." but seriously- great shot- nice "find" as we say, and great use of soft dreamy edges.', '2011-05-11 08:34:22.000000', NULL, 1),
